import pytest

from blib2to3.pgen2 import literals


def test_literal_round_trip_helper(capsys: pytest.CaptureFixture[str]) -> None:
    literals.test()

    assert capsys.readouterr().out == ""


def test_literal_helper_reports_mismatch(
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    original_eval_string = literals.evalString

    def mismatching_eval_string(source: str) -> str:
        if source == repr("A"):
            return "wrong"
        return original_eval_string(source)

    monkeypatch.setattr(literals, "evalString", mismatching_eval_string)

    literals.test()

    assert capsys.readouterr().out == "65 A 'A' wrong\n"
